function best_trade(prices) {
  let lowest = Infinity;
  let best = 0;
  for (const p of prices) {
    lowest = Math.min(lowest, p);
    best = Math.max(best, p - lowest);
  }
  return best;
}

referenceSolution.java:
class Solution {
    public int bestTrade(int[] prices) {
        int lowest = Integer.MAX_VALUE;
        int best = 0;
        for (int p : prices) {
            lowest = Math.min(lowest, p);
            best = Math.max(best, p - lowest);
        }
        return best;
    }
}
